def transform(grid):
    h, w = len(grid), len(grid[0])
    # Colored diagonal tracks encode a cyclic pattern by (row + column) phase.
    sums = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0:
                sums[r + c] = value
    # Horizontal stripes are the other encoding: each non-background row
    # assigns its color to its row-index phase in a cycle of stripe count.
    active_rows = {r: row[0] for r, row in enumerate(grid)
                   if row and row[0] != 0 and all(v == row[0] for v in row)}
    if active_rows and all(all(v == row[0] for v in row) for row in grid):
        period = len(active_rows)
        phase_color = {r % period: color for r, color in active_rows.items()}
        return [[phase_color[r % period]] * w for r in range(h)]
    period = len(sums)
    phase_color = {s % period: color for s, color in sums.items()}
    return [[phase_color[(r + c) % period] for c in range(w)] for r in range(h)]
